CREATE VIEW "public"."llm_usage_by_month" AS (SELECT date_trunc('month'::text, c.created_at)::date AS month, c.kind, c.model, c.provider, count(*) AS calls, sum(c.input_tokens) AS input_tokens, sum(c.output_tokens) AS output_tokens, count(*) FILTER (WHERE c.rejected) AS rejected_calls, count(*) FILTER (WHERE c.parse_failed) AS parse_failures FROM email_llm_calls c GROUP BY (date_trunc('month'::text, c.created_at)::date), c.kind, c.model, c.provider);--> statement-breakpoint
CREATE VIEW "books"."usage_by_month" AS (SELECT date_trunc('month'::text, u."on"::timestamp with time zone)::date AS month, u.provider, u.service, u.currency, sum(u.amount) AS amount FROM books.usage u GROUP BY (date_trunc('month'::text, u."on"::timestamp with time zone)::date), u.provider, u.service, u.currency);